function auditTabs(page){
  const tabs=document.createElement('nav');tabs.className='audit-tabs';tabs.setAttribute('aria-label','Подразделы');
  const items=auditNavigation.statistics.includes(page)?[['dashboard','Результаты','crystal'],['progress','Разбор сделок','book'],['digest','Отчёты','torch'],['coach','Рекомендации','shield']]:[['overview','Рынок сейчас','crystal'],['premarket','Контекст и события','book']];
  for(const [id,label,item] of items){const button=document.createElement('button');button.type='button';button.dataset.auditPage=id;button.innerHTML=worldProtocolItem(item)+'<span>'+label+'</span>';button.addEventListener('click',()=>showPage(id));tabs.append(button);}
  return tabs;
}
function auditMoneyPanel(page){
  const root=document.getElementById('page-'+page);if(!root)return;
  let host=root.querySelector('.audit-money');if(!host){host=document.createElement('div');host.className='audit-money';root.querySelector('.audit-tabs')?.after(host);}
  const closed=typeof ledgerClosed==='function'?ledgerClosed(allTrades||[]):(allTrades||[]).filter(t=>t.status!=='open');
  const raw=page==='digest'?closed.filter(t=>new Date(t.created_at).getTime()>=Date.now()-auditReportDays*86400000):page==='dashboard'?edgePeriodTrades(closed):page==='progress'&&typeof reviewPeriodTrades==='function'?reviewPeriodTrades(closed):closed;
  const stats=terminalStats(raw),cash=auditCashSummary(stats.valid),fmt=n=>n==null?'—':terminalFormatUsd(n);
  host.innerHTML=[['Денежный P&L',fmt(cash.total),cash.known+'/'+cash.count+' сделок с денежным результатом'],['Результат в R',stats.rCount?edgeFmtR(stats.netR,true):'—',stats.rCount+'/'+stats.valid.length+' сделок с измеримым R'],['Просадка в $',fmt(cash.drawdown==null?null:-cash.drawdown),'От пика закрытого результата выбранного периода']].map(([label,value,copy])=>'<article><span>'+label+'</span><strong>'+value+'</strong><small>'+copy+'</small></article>').join('');
  let note=root.querySelector('.audit-stats-note');if(!note){note=document.createElement('div');note.className='audit-note audit-stats-note';host.after(note);}
  note.textContent='Проценты отдельных позиций не складываются в ROI счёта. R вычисляется по входу, выходу и исходному стопу; сделки без этих цен не подтверждают R-статистику. '+(!cash.complete?'Часть денежного результата неизвестна. ':'')+(stats.rCount<stats.valid.length?'Часть выборки не имеет измеримого R. ':'')+(stats.valid.length<5?'Для устойчивых выводов пока недостаточно сделок.':'');
}
